#include "field_qq.hpp"
#include <array>
using Mon=array<int,9>;
int main(int argc,char**argv){fmpq_mpoly_ctx_init(ctx,2,ORD_LEX);{ifstream in(argv[1]);ofstream out(argv[2]);ofstream facts(string(argv[2])+".contents");int nr;in>>nr;vector<int>keep={0,1,2,3,4,6,8};out<<nr<<'\n';fmpq_t cf;fmpq_init(cf);for(int rr=0;rr<nr;rr++){int id,n;in>>id>>n;map<Mon,Rat>row;for(int k=0;k<n;k++){string cs;in>>cs;int m[16];for(int j=0;j<16;j++)in>>m[j];bool bad=false;for(int j=2;j<7;j++)bad|=m[j]!=0;bad|=m[12]!=0||m[14]!=0;if(bad)continue;assert(!fmpq_set_str(cf,cs.c_str(),10));fmpq_canonicalise(cf);Mon mon{};for(int j=0;j<9;j++)mon[j]=m[7+j];ulong ex[2]={(ulong)m[0],(ulong)m[1]};fmpq_mpoly_push_term_fmpq_ui(row[mon].n,cf,ex,ctx);}in>>n;for(int k=0;k<n;k++){string cs;int m;in>>cs;for(int j=0;j<16;j++)in>>m;}Rat g,tmp;for(auto&[m,v]:row){fmpq_mpoly_sort_terms(v.n,ctx);fmpq_mpoly_combine_like_terms(v.n,ctx);assert(fmpq_mpoly_gcd(tmp.n,g.n,v.n,ctx));fmpq_mpoly_swap(tmp.n,g.n,ctx);}facts<<id<<'\n';writepoly(facts,g.n);out<<id<<' '<<row.size()<<'\n';for(auto&[m,v]:row){assert(fmpq_mpoly_divides(tmp.n,v.n,g.n,ctx));for(auto j:keep)out<<m[j]<<' ';out<<'\n';writepoly(out,tmp.n);}cerr<<"row "<<id<<" coefficients "<<row.size()<<" gcddegree "<<fmpq_mpoly_total_degree_si(g.n,ctx)<<'\n';}fmpq_clear(cf);}fmpq_mpoly_ctx_clear(ctx);flint_cleanup();}
